@Configuration
class WebConfig implements WebMvcConfigurer {
    @Override public void addInterceptors(InterceptorRegistry registry) {
        registry.addInterceptor(new HandlerInterceptor() {
            @Override public boolean preHandle(HttpServletRequest rq, HttpServletResponse rs, Object h) {
                return policy.allows(rq);            // false short-circuits the chain
            }
            @Override public void afterCompletion(HttpServletRequest rq, HttpServletResponse rs,
                                                  Object h, Exception ex) { audit(rq, ex); }
        });
    }
}
